const recountDiscussion = `-- name: RecountDiscussion :one
UPDATE discussions d SET
    state = (SELECT op.state FROM discussion_posts op WHERE op.workspace_id = d.workspace_id AND op.id = d.opening_post_id),
    reply_count = (SELECT count(*) FROM discussion_posts p
                   WHERE p.workspace_id = d.workspace_id AND p.discussion_id = d.id AND NOT p.opening
                     AND p.state = 'published' AND p.deleted_at IS NULL),
    pending_posts = (SELECT count(*) FROM discussion_posts p
                     WHERE p.workspace_id = d.workspace_id AND p.discussion_id = d.id
                       AND p.state = 'pending' AND p.deleted_at IS NULL),
    hidden_posts = (SELECT count(*) FROM discussion_posts p
                    WHERE p.workspace_id = d.workspace_id AND p.discussion_id = d.id
                      AND p.state = 'hidden' AND p.deleted_at IS NULL),
    last_activity_at = greatest(d.created_at, coalesce((SELECT max(p.created_at) FROM discussion_posts p
                        WHERE p.workspace_id = d.workspace_id AND p.discussion_id = d.id
                          AND p.state = 'published' AND p.deleted_at IS NULL), d.created_at))
WHERE d.workspace_id = $1 AND d.id = $2
RETURNING id, workspace_id, inbox_id, channel_id, page, page_title, title, opening_post_id, state, locked_at, answer_post_id, answered_at, reply_count, pending_posts, hidden_posts, conversation_id, created_at, last_activity_at, kind, board_id, stage, stage_changed_at, vote_count, search
`

type RecountDiscussionParams struct {
	WorkspaceID uuid.UUID
	ID          uuid.UUID
}

func (q *Queries) RecountDiscussion(ctx context.Context, arg RecountDiscussionParams) (Discussion, error) {
	row := q.db.QueryRow(ctx, recountDiscussion, arg.WorkspaceID, arg.ID)
	var i Discussion
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.InboxID,
		&i.ChannelID,
		&i.Page,
		&i.PageTitle,
		&i.Title,
		&i.OpeningPostID,
		&i.State,
		&i.LockedAt,
		&i.AnswerPostID,
		&i.AnsweredAt,
		&i.ReplyCount,
		&i.PendingPosts,
		&i.HiddenPosts,
		&i.ConversationID,
		&i.CreatedAt,
		&i.LastActivityAt,
		&i.Kind,
		&i.BoardID,
		&i.Stage,
		&i.StageChangedAt,
		&i.VoteCount,
		&i.Search,
	)
	return i, err
}

